/* KASITU Webs Business Manager — Phase 4 Payments */
const content=document.getElementById('appContent'),title=document.getElementById('pageTitle'),sidebar=document.getElementById('sidebar'),modal=document.getElementById('modalBackdrop'),modalTitle=document.getElementById('modalTitle'),form=document.getElementById('recordForm');
let clients=[],leads=[],quotations=[],invoices=[],payments=[],projects=[],maintenance=[],expenses=[],documents=[],projectsReady=true,maintenanceReady=true,expensesReady=true,documentsReady=true;
let businessSettings={business_name:'KASITU Webs',contact_name:'',email:'info@kasituwebs.co.za',phone:'079 348 0103',website:'https://kasituwebs.co.za',address:'',default_quote_validity_days:14,default_deposit_rate:50,default_vat_rate:0},settingsReady=false,settingsLoadError='';
let currentRole='owner',currentStatus='active',currentOwnerId=null;
const roleRules={
 owner:{views:['dashboard','clients','leads','quotations','invoices','payments','projects','maintenance','expenses','documents','reports','settings','account','team','audit'],writes:['clients','leads','quotations','invoices','payments','projects','maintenance','expenses','documents']},
 manager:{views:['dashboard','clients','leads','quotations','invoices','payments','projects','maintenance','expenses','documents','reports','account'],writes:['clients','leads','quotations','invoices','payments','projects','maintenance','expenses','documents']},
 staff:{views:['dashboard','clients','leads','quotations','invoices','payments','projects','maintenance','documents','account'],writes:['clients','leads','quotations','invoices','payments']},
 viewer:{views:['dashboard','clients','leads','quotations','invoices','payments','projects','maintenance','expenses','documents','reports','account'],writes:[]}
};
function canView(view){return !!(roleRules[currentRole]?.views||roleRules.owner.views).includes(view)}
function canWrite(module){return !!(roleRules[currentRole]?.writes||[]).includes(module)}
function requireWrite(module){if(canWrite(module))return true;alert('Your '+String(currentRole).toUpperCase()+' role is read-only for this area.');return false}
function applyRoleUI(){document.querySelectorAll('.nav-item[data-view]').forEach(btn=>{btn.hidden=!canView(btn.dataset.view)});document.querySelectorAll('[data-add]').forEach(btn=>{if(!canWrite(btn.dataset.add))btn.hidden=true});document.querySelectorAll('[data-edit-client],[data-edit-lead],[data-edit-quote],[data-create-invoice],[data-edit-invoice],[data-edit-payment],[data-edit-project],[data-edit-maintenance],[data-edit-expense],[data-delete-expense],[data-edit-document],[data-delete-document]').forEach(btn=>{if(currentRole==='viewer'||(btn.dataset.editExpense&&!canWrite('expenses'))||(btn.dataset.deleteExpense&&!canWrite('expenses'))||(btn.dataset.editDocument&&!canWrite('documents'))||(btn.dataset.deleteDocument&&!canWrite('documents'))||(btn.dataset.editProject&&!canWrite('projects'))||(btn.dataset.editMaintenance&&!canWrite('maintenance'))||btn.dataset.editClient&&!canWrite('clients')||btn.dataset.editLead&&!canWrite('leads')||btn.dataset.editQuote&&!canWrite('quotations')||btn.dataset.createInvoice&&!canWrite('invoices')||btn.dataset.editInvoice&&!canWrite('invoices')||btn.dataset.editPayment&&!canWrite('payments'))btn.hidden=true});const badge=document.querySelector('.topbar-actions .mode-badge');if(badge)badge.textContent=String(currentRole).toUpperCase()+' ACCESS'}
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]));
const money=n=>`R${Number(n||0).toLocaleString('en-ZA',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
const today=()=>new Date().toISOString().slice(0,10);
const addDays=(date,days)=>{const d=new Date(date+'T00:00:00');d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)};
async function getDataOwnerId(session){const {data,error}=await window.kasituSupabase.from('business_members').select('business_owner_id,role,status').eq('user_id',session.user.id).maybeSingle();if(error)throw error;if(!data||data.status!=='active')throw new Error('Your Business Manager access is inactive.');currentRole=data.role||'owner';currentStatus=data.status;currentOwnerId=data.business_owner_id||session.user.id;return currentOwnerId}
async function getSession(){const {data,error}=await window.kasituSupabase.auth.getSession();if(error||!data.session){window.location.replace('login.html');return null}return data.session}
async function loadData(){
 const session=await getSession();if(!session)return false;
 await getDataOwnerId(session);
 const [cr,lr,qr,ir,pr,xr,mr,er,dr]=await Promise.all([window.kasituSupabase.from('clients').select('*').order('created_at',{ascending:true}),window.kasituSupabase.from('leads').select('*').order('created_at',{ascending:false}),window.kasituSupabase.from('quotations').select('*').order('created_at',{ascending:false}),window.kasituSupabase.from('invoices').select('*').order('created_at',{ascending:false}),window.kasituSupabase.from('payments').select('*').order('payment_date',{ascending:false}).order('created_at',{ascending:false}),window.kasituSupabase.from('projects').select('*').order('created_at',{ascending:false}),window.kasituSupabase.from('maintenance').select('*').order('created_at',{ascending:false}),window.kasituSupabase.from('expenses').select('*').order('expense_date',{ascending:false}).order('created_at',{ascending:false}),window.kasituSupabase.from('documents').select('*').order('created_at',{ascending:false})]);
 if(cr.error||lr.error||qr.error||ir.error||pr.error){console.error(cr.error||lr.error||qr.error||ir.error||pr.error);content.innerHTML='<div class="panel"><h2>Database setup required</h2><p>Check your existing Business Manager database setup, then refresh.</p></div>';return false}
 projectsReady=!xr.error;if(xr.error)console.warn('Projects module setup required. Run projects-schema.sql in Supabase.',xr.error);
 clients=cr.data.map(c=>({id:c.client_code,business:c.business_name,contact:c.contact_name||'',email:c.email||'',phone:c.phone||'',service:c.service||'',status:c.status,notes:c.notes||'',_id:c.id}));
 leads=lr.data.map(l=>({id:l.id,business:l.business_name,contact:l.contact_name||'',phone:l.phone||'',email:l.email||'',service:l.service_requested||'',status:l.status,followUp:l.follow_up_date||'',source:l.source||'',notes:l.notes||'',date:l.created_at?.slice(0,10)||''}));
 quotations=qr.data.map(q=>({...q,items:Array.isArray(q.line_items)?q.line_items:[]}));
invoices=ir.data.map(i=>({...i,items:Array.isArray(i.line_items)?i.line_items:[]}));
payments=pr.data.map(p=>({...p}));
projects=projectsReady?(xr.data||[]).map(p=>({...p})):[];
 maintenanceReady=!mr.error;if(mr.error)console.warn('Maintenance module setup required. Run maintenance-schema.sql in Supabase.',mr.error);
 maintenance=maintenanceReady?(mr.data||[]).map(m=>({...m})):[];
 expensesReady=!er.error;if(er.error)console.warn('Expenses module setup required. Run expenses-schema.sql in Supabase.',er.error);
 expenses=expensesReady?(er.data||[]).map(x=>({...x})):[];
 documentsReady=!dr.error;if(dr.error)console.warn('Documents module setup required. Run documents-schema.sql in Supabase.',dr.error);
 documents=documentsReady?(dr.data||[]).map(d=>({...d})):[];
 return true
}
function renderDashboard(){
 title.textContent='Dashboard';
 const active=clients.filter(c=>c.status==='Active').length;
 const openLeads=leads.filter(l=>!['Won','Lost'].includes(l.status)).length;
 const wonLeads=leads.filter(l=>l.status==='Won').length;
 const approved=quotations.filter(q=>q.status==='Approved').length;
 const outstanding=invoices.reduce((s,i)=>s+Number(i.balance_due||0),0);
 const revenue=payments.reduce((s,p)=>s+Number(p.amount||0),0);
 const totalExpenses=expenses.reduce((s,e)=>s+Number(e.amount||0),0);
 const profit=revenue-totalExpenses;
 const overdueInvoices=invoices.filter(i=>Number(i.balance_due||0)>0&&i.due_date&&i.due_date<today()&&!['Paid','Cancelled'].includes(i.status));
 const followUpsDue=leads.filter(l=>l.followUp&&l.followUp<=today()&&!['Won','Lost'].includes(l.status));
 const projectOpen=projects.filter(p=>!['Completed','Cancelled'].includes(p.status));
 const projectComplete=projects.filter(p=>p.status==='Completed').length;
 const quoteRate=quotations.length?Math.round(approved/quotations.length*100):0;
 const leadRate=leads.length?Math.round(wonLeads/leads.length*100):0;
 const months=[];
 for(let n=5;n>=0;n--){const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-n);const key=d.toISOString().slice(0,7);months.push({key,label:d.toLocaleDateString('en-ZA',{month:'short'}),income:payments.filter(p=>(p.payment_date||'').slice(0,7)===key).reduce((s,p)=>s+Number(p.amount||0),0),expense:expenses.filter(e=>(e.expense_date||'').slice(0,7)===key).reduce((s,e)=>s+Number(e.amount||0),0)})}
 const maxMonthly=Math.max(1,...months.flatMap(m=>[m.income,m.expense]));
 const monthChart=months.map(m=>'<div class="analytics-month"><div class="analytics-bars"><div class="analytics-bar income" style="height:'+Math.max(m.income?4:0,Math.round(m.income/maxMonthly*100))+'%" title="Income '+money(m.income)+'"></div><div class="analytics-bar expense" style="height:'+Math.max(m.expense?4:0,Math.round(m.expense/maxMonthly*100))+'%" title="Expenses '+money(m.expense)+'"></div></div><span>'+esc(m.label)+'</span><small>'+money(m.income-m.expense)+'</small></div>').join('');
 const pipeline=[['New',leads.filter(l=>l.status==='New').length],['Contacted',leads.filter(l=>l.status==='Contacted').length],['Quoted',leads.filter(l=>l.status==='Quoted').length],['Won',wonLeads],['Lost',leads.filter(l=>l.status==='Lost').length]];
 const pipelineTotal=Math.max(1,leads.length);
 content.innerHTML=`<div class="hero-copy analytics-hero"><div><span class="analytics-kicker">BUSINESS OVERVIEW</span><h2>Your business, at a glance.</h2><p>Track cash flow, sales opportunities and delivery progress from one place.</p></div><span class="analytics-period">Last 6 months · ${esc(new Date().toLocaleDateString('en-ZA',{month:'long',year:'numeric'}))}</span></div>
 <div class="stats analytics-stats">
 <div class="stat"><div class="stat-label">Income Received</div><div class="stat-value">${money(revenue)}</div><div class="stat-note">Payments recorded</div></div>
 <div class="stat"><div class="stat-label">Expenses</div><div class="stat-value">${money(totalExpenses)}</div><div class="stat-note">All recorded expenses</div></div>
 <div class="stat"><div class="stat-label">Net Cash Difference</div><div class="stat-value">${money(profit)}</div><div class="stat-note">Income received minus expenses</div></div>
 <div class="stat"><div class="stat-label">Outstanding Invoices</div><div class="stat-value">${money(outstanding)}</div><div class="stat-note">${overdueInvoices.length} overdue invoice${overdueInvoices.length===1?'':'s'}</div></div>
 <div class="stat"><div class="stat-label">Active Clients</div><div class="stat-value">${active}</div><div class="stat-note">${clients.length} total clients</div></div>
 <div class="stat"><div class="stat-label">Open Leads</div><div class="stat-value">${openLeads}</div><div class="stat-note">${leadRate}% lead win rate</div></div>
 <div class="stat"><div class="stat-label">Projects In Progress</div><div class="stat-value">${projectOpen.length}</div><div class="stat-note">${projectComplete} completed</div></div>
 </div>
 <div class="analytics-grid">
 <div class="panel analytics-panel"><div class="panel-head"><div><h3>Income vs Expenses</h3><p class="panel-subtitle">Monthly totals based on recorded dates.</p></div><button class="btn" data-go="reports">Open reports</button></div><div class="analytics-legend"><span><i class="legend-income"></i>Income</span><span><i class="legend-expense"></i>Expenses</span></div><div class="analytics-chart">${monthChart}</div><div class="analytics-footnote">Bars show each month relative to the highest monthly amount in this period.</div></div>
 <div class="panel analytics-panel"><div class="panel-head"><div><h3>Sales Pipeline</h3><p class="panel-subtitle">Where your enquiries currently stand.</p></div><button class="btn" data-go="leads">Manage leads</button></div><div class="pipeline-total"><strong>${leads.length}</strong><span>total leads</span><b>${leadRate}% won</b></div><div class="pipeline-list">${pipeline.map(([label,count])=>'<div class="pipeline-row"><div><span>'+esc(label)+'</span><strong>'+count+'</strong></div><div class="pipeline-track"><i style="width:'+Math.round(count/pipelineTotal*100)+'%"></i></div></div>').join('')}</div><div class="analytics-mini-metrics"><div><span>Quotations approved</span><strong>${approved} / ${quotations.length}</strong></div><div><span>Approval rate</span><strong>${quoteRate}%</strong></div></div></div>
 </div>
 <div class="analytics-grid analytics-grid-bottom">
 <div class="panel"><div class="panel-head"><div><h3>Needs Attention</h3><p class="panel-subtitle">Items that may need action soon.</p></div></div><div class="attention-list">${overdueInvoices.length?'<button class="attention-item danger" data-go="invoices"><span>🔴</span><div><strong>'+overdueInvoices.length+' overdue invoice'+(overdueInvoices.length===1?'':'s')+'</strong><small>Review unpaid balances past their due date.</small></div><b>›</b></button>':''}${followUpsDue.length?'<button class="attention-item warning" data-go="leads"><span>📞</span><div><strong>'+followUpsDue.length+' lead follow-up'+(followUpsDue.length===1?'':'s')+' due</strong><small>Follow-ups due today or earlier.</small></div><b>›</b></button>':''}${!overdueInvoices.length&&!followUpsDue.length?'<div class="empty">Nothing urgent from invoices or lead follow-ups.</div>':''}</div></div>
 <div class="panel"><div class="panel-head"><div><h3>Quick Business Snapshot</h3><p class="panel-subtitle">Your current workload.</p></div></div><div class="snapshot-list"><button data-go="quotations"><span>Quotations</span><strong>${quotations.length}</strong><small>${approved} approved</small></button><button data-go="invoices"><span>Invoices</span><strong>${invoices.length}</strong><small>${money(outstanding)} outstanding</small></button><button data-go="maintenance"><span>Maintenance</span><strong>${maintenance.filter(m=>!['Completed','Cancelled'].includes(m.status)).length}</strong><small>Open service records</small></button><button data-go="projects"><span>Projects</span><strong>${projects.length}</strong><small>${projectComplete} completed</small></button></div></div>
 </div>
 <div class="grid-2"><div class="panel"><div class="panel-head"><h3>Recent Clients</h3><button class="btn" data-go="clients">View all</button></div>${clientTable(clients.slice(-5).reverse())}</div><div class="panel"><div class="panel-head"><h3>Recent Quotations</h3><button class="btn" data-go="quotations">View all</button></div>${quoteMini()}</div></div>`;
 bindNavigationButtons()
}
function clientTable(rows){if(!rows.length)return '<div class="empty">No clients yet.</div>';return `<div class="table-wrap"><table class="table"><thead><tr><th>Client</th><th>Service</th><th>Status</th></tr></thead><tbody>${rows.map(c=>`<tr><td><strong>${esc(c.business)}</strong><br><span style="color:var(--muted)">${esc(c.id)}</span></td><td>${esc(c.service||'—')}</td><td><span class="badge">${esc(c.status)}</span></td></tr>`).join('')}</tbody></table></div>`}
function leadSummary(){if(!leads.length)return '<div class="empty">No leads yet.<br><br><button class="btn primary" data-add="lead">Add your first lead</button></div>';const counts={New:0,Contacted:0,Quoted:0,Won:0,Lost:0};leads.forEach(l=>counts[l.status]=(counts[l.status]||0)+1);return Object.entries(counts).map(([k,v])=>`<div style="display:flex;justify-content:space-between;padding:12px 0;border-bottom:1px solid var(--border);font-size:12px"><span>${k}</span><strong>${v}</strong></div>`).join('')}
function renderClients(filter=''){title.textContent='Clients';const rows=clients.filter(c=>`${c.business} ${c.contact} ${c.email} ${c.id}`.toLowerCase().includes(filter.toLowerCase()));content.innerHTML=`<div class="section-head"><div><h2>Clients</h2><p>Your central client register and client IDs.</p></div><div style="display:flex;gap:9px"><input id="clientSearch" class="search" placeholder="Search clients..." value="${esc(filter)}"><button class="btn primary" data-add="client">+ Add Client</button></div></div><div class="panel">${clientTableDetailed(rows)}</div>`;document.getElementById('clientSearch').addEventListener('input',e=>renderClients(e.target.value))}
function clientTableDetailed(rows){if(!rows.length)return '<div class="empty">No matching clients.</div>';return `<div class="table-wrap"><table class="table"><thead><tr><th>Client ID</th><th>Business</th><th>Contact</th><th>Service</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr><td>${esc(c.id)}</td><td><strong>${esc(c.business)}</strong></td><td>${esc(c.contact||'—')}<br><span style="color:var(--muted)">${esc(c.phone||c.email||'')}</span></td><td>${esc(c.service||'—')}</td><td><span class="badge">${esc(c.status)}</span></td><td><button class="btn" data-edit-client="${esc(c.id)}">Edit</button></td></tr>`).join('')}</tbody></table></div>`}
function renderLeads(filter=''){title.textContent='Leads';const rows=leads.filter(l=>`${l.business} ${l.contact} ${l.service} ${l.status}`.toLowerCase().includes(filter.toLowerCase()));content.innerHTML=`<div class="section-head"><div><h2>Lead Pipeline</h2><p>Track enquiries from first contact to won or lost.</p></div><div style="display:flex;gap:9px"><input id="leadSearch" class="search" placeholder="Search leads..." value="${esc(filter)}"><button class="btn primary" data-add="lead">+ Add Lead</button></div></div><div class="panel">${leadTable(rows)}</div>`;document.getElementById('leadSearch').addEventListener('input',e=>renderLeads(e.target.value))}
function leadTable(rows){if(!rows.length)return '<div class="empty">No leads yet. Add every genuine enquiry here so no opportunity gets forgotten.</div>';return `<div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Business / Person</th><th>Service</th><th>Status</th><th>Follow-up</th><th></th></tr></thead><tbody>${rows.map(l=>`<tr><td>${esc(l.date||'—')}</td><td><strong>${esc(l.business)}</strong><br><span style="color:var(--muted)">${esc(l.contact||'')}</span></td><td>${esc(l.service||'—')}</td><td><span class="badge">${esc(l.status)}</span></td><td>${esc(l.followUp||'—')}</td><td><button class="btn" data-edit-lead="${esc(l.id)}">Edit</button></td></tr>`).join('')}</tbody></table></div>`}

function invoiceStatus(s){return `<span class="invoice-status ${String(s||'Draft').toLowerCase().replace(/\s+/g,'-')}">${esc(s||'Draft')}</span>`}
function invoiceMini(){if(!invoices.length)return '<div class="empty">No invoices yet.<br><br><button class="btn primary" data-add="invoice">Create first invoice</button></div>';return invoices.slice(0,5).map(i=>`<div class="invoice-card"><div class="invoice-card-head"><div><div class="invoice-number">${esc(i.invoice_number)}</div><strong>${esc(i.client_name)}</strong></div><div style="text-align:right"><div class="invoice-total">${money(i.total)}</div>${invoiceStatus(i.status)}</div></div></div>`).join('')}
function renderInvoices(filter=''){title.textContent='Invoices';const rows=invoices.filter(i=>`${i.invoice_number} ${i.client_name} ${i.status}`.toLowerCase().includes(filter.toLowerCase()));content.innerHTML=`<div class="section-head"><div><h2>Invoices</h2><p>Create invoices from quotations, track balances and payment status.</p></div><div class="quote-toolbar"><input id="invoiceSearch" class="search" placeholder="Search invoices..." value="${esc(filter)}"><button class="btn primary" data-add="invoice">+ New Invoice</button></div></div><div class="panel">${invoiceTable(rows)}</div>`;document.getElementById('invoiceSearch').addEventListener('input',e=>renderInvoices(e.target.value))}
function invoiceTable(rows){if(!rows.length)return '<div class="empty">No invoices found. Create an invoice from a quotation.</div>';return `<div class="table-wrap"><table class="table"><thead><tr><th>Invoice</th><th>Client</th><th>Date</th><th>Due</th><th>Status</th><th>Total</th><th>Balance</th><th></th></tr></thead><tbody>${rows.map(i=>`<tr><td><strong>${esc(i.invoice_number)}</strong></td><td>${esc(i.client_name)}</td><td>${esc(i.invoice_date||'—')}</td><td>${esc(i.due_date||'—')}</td><td>${invoiceStatus(i.status)}</td><td><strong>${money(i.total)}</strong></td><td><strong>${money(i.balance_due)}</strong></td><td><button class="btn" data-edit-invoice="${esc(i.id)}">Edit</button></td></tr>`).join('')}</tbody></table></div>`}
function renderPayments(filter=''){
title.textContent='Payments';
const rows=payments.filter(p=>(p.payment_number+' '+(p.invoice_number||'')+' '+(p.client_name||'')+' '+(p.method||'')+' '+(p.reference||'')).toLowerCase().includes(filter.toLowerCase()));
content.innerHTML='<div class="section-head"><div><h2>Payments</h2><p>Record payments received and keep invoice balances up to date.</p></div><div class="quote-toolbar"><input id="paymentSearch" class="search" placeholder="Search payments..." value="'+esc(filter)+'"><button class="btn primary" data-add="payment">+ Record Payment</button></div></div><div class="panel">'+paymentTable(rows)+'</div>';
document.getElementById('paymentSearch').addEventListener('input',e=>renderPayments(e.target.value))}
function paymentTable(rows){if(!rows.length)return '<div class="empty">No payments recorded yet. Record your first payment against an invoice.</div>';return '<div class="table-wrap"><table class="table"><thead><tr><th>Payment</th><th>Invoice</th><th>Client</th><th>Date</th><th>Method</th><th>Reference</th><th>Amount</th><th></th></tr></thead><tbody>'+rows.map(p=>'<tr><td><strong>'+esc(p.payment_number)+'</strong></td><td>'+esc(p.invoice_number||'—')+'</td><td>'+esc(p.client_name||'—')+'</td><td>'+esc(p.payment_date||'—')+'</td><td>'+esc(p.method||'—')+'</td><td>'+esc(p.reference||'—')+'</td><td><strong>'+money(p.amount)+'</strong></td><td><button class="btn" data-edit-payment="'+esc(p.id)+'">Edit</button></td></tr>').join('')+'</tbody></table></div>'}
function paymentInvoiceOptions(selected=''){return '<option value="">Select an invoice...</option>'+invoices.map(i=>'<option value="'+esc(i.id)+'" '+(i.id===selected?'selected':'')+'>'+esc(i.invoice_number)+' — '+esc(i.client_name)+' — Balance '+money(i.balance_due)+'</option>').join('')}
function paymentForm(p={}){p=p||{};return '<div class="form-grid"><div class="field"><label>Invoice *</label><select name="invoice_id" required>'+paymentInvoiceOptions(p.invoice_id||'')+'</select></div><div class="field"><label>Payment number</label><input name="payment_number" value="'+esc(p.payment_number||'')+'" placeholder="Auto-generated on save" readonly></div><div class="field"><label>Payment date *</label><input type="date" name="payment_date" value="'+esc(p.payment_date||today())+'" required></div><div class="field"><label>Amount (R) *</label><input name="amount" type="number" min="0.01" step="0.01" value="'+Number(p.amount||0).toFixed(2)+'" required></div><div class="field"><label>Payment method *</label><select name="method">'+['EFT','Cash','Card','PayPal','Other'].map(x=>'<option '+(x===(p.method||'EFT')?'selected':'')+'>'+x+'</option>').join('')+'</select></div><div class="field"><label>Payment reference</label><input name="reference" value="'+esc(p.reference||'')+'" placeholder="Bank reference / receipt number"></div><div class="field" style="grid-column:1/-1"><label>Notes</label><textarea name="notes" placeholder="Optional payment notes">'+esc(p.notes||'')+'</textarea></div></div><div class="quote-summary" id="paymentSummary"></div><div class="form-actions"><button type="button" class="btn" id="cancelModal">Cancel</button><button class="btn primary">Save Payment</button></div>'}
function calculatePayment(){const invoiceId=form.querySelector('[name="invoice_id"]')?.value,invoice=invoices.find(i=>i.id===invoiceId),amount=Math.max(0,Number(form.querySelector('[name="amount"]')?.value||0));if(!invoice){form.querySelector('#paymentSummary').innerHTML='<div class="empty">Select an invoice to see its balance.</div>';return {invoice:null,amount:0,newPaid:0,newBalance:0}}const allRecorded=payments.filter(p=>p.invoice_id===invoice.id),recordedTotal=allRecorded.reduce((s,p)=>s+Number(p.amount||0),0),recordedBefore=allRecorded.filter(p=>p.id!==form.dataset.paymentId).reduce((s,p)=>s+Number(p.amount||0),0),openingPaid=Math.max(0,Number(invoice.amount_paid||0)-recordedTotal),previouslyPaid=openingPaid+recordedBefore,newPaid=Math.min(Number(invoice.total||0),previouslyPaid+amount),newBalance=Math.max(0,Number(invoice.total||0)-newPaid);form.querySelector('#paymentSummary').innerHTML='<div class="quote-summary-row"><span>Invoice total</span><strong>'+money(invoice.total)+'</strong></div><div class="quote-summary-row"><span>Previously paid</span><strong>'+money(openingPaid)+'</strong></div><div class="quote-summary-row"><span>This payment</span><strong>'+money(amount)+'</strong></div><div class="quote-summary-row total"><span>New balance</span><strong>'+money(newBalance)+'</strong></div>';return {invoice,amount,newPaid,newBalance}}
async function nextPaymentNumber(session){const ownerId=await getDataOwnerId(session);const {data,error}=await window.kasituSupabase.from('payments').select('payment_number').eq('owner_id',ownerId);if(error)throw error;const nums=(data||[]).map(r=>Number(String(r.payment_number||'').match(/^KAS-P-\d{4}-(\d+)$/)?.[1]||0)).filter(Number.isFinite);return 'KAS-P-'+new Date().getFullYear()+'-'+String(Math.max(0,...nums)+1).padStart(3,'0')}
async function savePayment(existing){const session=await getSession();if(!session)return;const v=values(),calc=calculatePayment();if(!calc.invoice){alert('Please select an invoice.');return}if(calc.amount<=0){alert('Enter a payment amount greater than R0.');return}if(calc.amount>Number(calc.invoice.total||0)){alert('Payment cannot be greater than the invoice total.');return}let paymentNumber=existing?.payment_number;if(!paymentNumber)try{paymentNumber=await nextPaymentNumber(session)}catch(e){alert(e.message);return}const allRecorded=payments.filter(p=>p.invoice_id===calc.invoice.id),recordedTotal=allRecorded.reduce((s,p)=>s+Number(p.amount||0),0),recordedBefore=allRecorded.filter(p=>p.id!==existing?.id).reduce((s,p)=>s+Number(p.amount||0),0),openingPaid=Math.max(0,Number(calc.invoice.amount_paid||0)-recordedTotal),newPaid=Math.min(Number(calc.invoice.total||0),openingPaid+recordedBefore+calc.amount),newBalance=Math.max(0,Number(calc.invoice.total||0)-newPaid);let status=calc.invoice.status;if(newPaid>=Number(calc.invoice.total||0)&&Number(calc.invoice.total||0)>0)status='Paid';else if(newPaid>0)status='Partially Paid';else if(status==='Paid'||status==='Partially Paid')status='Draft';const ownerId=await getDataOwnerId(session);const payload={owner_id:ownerId,payment_number:paymentNumber,invoice_id:calc.invoice.id,client_id:calc.invoice.client_id,client_code:calc.invoice.client_code,client_name:calc.invoice.client_name,invoice_number:calc.invoice.invoice_number,payment_date:v.payment_date||today(),amount:calc.amount,method:v.method||'EFT',reference:v.reference||null,notes:v.notes||null};const result=existing?await window.kasituSupabase.from('payments').update(payload).eq('id',existing.id):await window.kasituSupabase.from('payments').insert(payload);if(result.error){alert(result.error.message);return}const invoiceResult=await window.kasituSupabase.from('invoices').update({amount_paid:newPaid,balance_due:newBalance,status}).eq('id',calc.invoice.id);if(invoiceResult.error){alert(invoiceResult.error.message);return}await logAudit(existing?'updated':'created','payments',existing?.id||null,paymentNumber,{amount:calc.amount,invoice:calc.invoice.invoice_number});await loadData();closeModal();renderPayments()}
function quotationOptions(selected=''){return '<option value="">Start without a quotation...</option>'+quotations.map(q=>`<option value="${esc(q.id)}" ${q.id===selected?'selected':''}>${esc(q.quote_number)} — ${esc(q.client_name)} — ${money(q.total)}</option>`).join('')}
function defaultInvoiceItems(i){return i?.items?.length?i.items:[{description:'',quantity:1,unit_price:0}]}
function invoiceForm(i={}){
 i=i||{};const valid=i.due_date||addDays(i.invoice_date||today(),7);
 return `<div class="form-grid"><div class="field"><label>Quotation</label><select name="quotation_id">${quotationOptions(i.quotation_id||'')}</select></div><div class="field"><label>Invoice number</label><input name="invoice_number" value="${esc(i.invoice_number||'')}" placeholder="Auto-generated on save" readonly></div><div class="field"><label>Invoice date *</label><input type="date" name="invoice_date" value="${esc(i.invoice_date||today())}" required></div><div class="field"><label>Due date</label><input type="date" name="due_date" value="${esc(valid)}"></div><div class="field"><label>Status</label><select name="status">${['Draft','Sent','Partially Paid','Paid','Overdue','Cancelled'].map(x=>`<option ${x===(i.status||'Draft')?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Amount paid (R)</label><input name="amount_paid" type="number" min="0" step="0.01" value="${Number(i.amount_paid||0).toFixed(2)}"></div><div class="field"><label>Discount (R)</label><input name="discount" type="number" min="0" step="0.01" value="${Number(i.discount||0).toFixed(2)}"></div><div class="field"><label>VAT rate (%)</label><input name="vat_rate" type="number" min="0" max="100" step="0.01" value="${Number(i.vat_rate||0)}"></div></div><div style="margin-top:20px"><div class="panel-head"><h3>Line items</h3><button type="button" class="btn" id="addInvoiceLine">+ Add item</button></div><div class="line-items" id="invoiceLines">${itemRows(defaultInvoiceItems(i)).replaceAll('name="item_qty"','name="invoice_qty"').replaceAll('name="item_price"','name="invoice_price"').replaceAll('name="item_description"','name="invoice_description"').replaceAll('name="item_total"','name="invoice_total"')}</div></div><div class="quote-summary" id="invoiceSummary"></div><div class="field" style="margin-top:20px"><label>Notes</label><textarea name="notes" placeholder="Optional invoice notes">${esc(i.notes||'')}</textarea></div><div class="field" style="margin-top:14px"><label>Terms & conditions</label><textarea name="terms" placeholder="Payment terms, due date, bank/payment details, etc.">${esc(i.terms||'Payment is due by the due date shown above. Please retain the invoice number as your payment reference.')}</textarea></div><div class="form-actions"><button type="button" class="btn" id="cancelModal">Cancel</button><button class="btn primary">Save Invoice</button></div>`}
function collectInvoiceItems(){return [...form.querySelectorAll('[data-line-row]')].map(row=>({description:row.querySelector('[name="invoice_description"]').value.trim(),quantity:Number(row.querySelector('[name="invoice_qty"]').value||0),unit_price:Number(row.querySelector('[name="invoice_price"]').value||0)})).filter(i=>i.description||i.unit_price>0)}
function calculateInvoice(){const items=collectInvoiceItems(),subtotal=items.reduce((s,i)=>s+i.quantity*i.unit_price,0),discount=Math.max(0,Number(form.querySelector('[name="discount"]')?.value||0)),taxable=Math.max(0,subtotal-discount),vatRate=Math.max(0,Number(form.querySelector('[name="vat_rate"]')?.value||0)),vat=taxable*vatRate/100,total=taxable+vat,paid=Math.min(total,Math.max(0,Number(form.querySelector('[name="amount_paid"]')?.value||0))),balance=Math.max(0,total-paid);form.querySelector('#invoiceSummary').innerHTML=`<div class="quote-summary-row"><span>Subtotal</span><strong>${money(subtotal)}</strong></div><div class="quote-summary-row"><span>Discount</span><strong>− ${money(discount)}</strong></div><div class="quote-summary-row"><span>VAT (${vatRate.toFixed(2)}%)</span><strong>${money(vat)}</strong></div><div class="quote-summary-row total"><span>Total</span><strong>${money(total)}</strong></div><div class="quote-summary-row"><span>Amount paid</span><strong>${money(paid)}</strong></div><div class="quote-summary-row"><span>Balance due</span><strong>${money(balance)}</strong></div>`;form.querySelectorAll('[data-line-row]').forEach(row=>{const qty=Number(row.querySelector('[name="invoice_qty"]').value||0),price=Number(row.querySelector('[name="invoice_price"]').value||0);row.querySelector('[name="invoice_total"]').value=money(qty*price)});return {items,subtotal,discount,vatRate,vat,total,paid,balance}}
async function nextInvoiceNumber(session){const ownerId=await getDataOwnerId(session);const {data,error}=await window.kasituSupabase.from('invoices').select('invoice_number').eq('owner_id',ownerId);if(error)throw error;const nums=(data||[]).map(r=>Number(String(r.invoice_number||'').match(/^KAS-I-\d{4}-(\d+)$/)?.[1]||0)).filter(Number.isFinite);return `KAS-I-${new Date().getFullYear()}-${String(Math.max(0,...nums)+1).padStart(3,'0')}`}
const isUuid=v=>/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(v||''));
async function saveInvoice(existing){
 const session=await getSession();if(!session)return;
 const v=values(),calc=calculateInvoice();
 const quotationId=isUuid(v.quotation_id)?v.quotation_id:null;
 let quote=quotationId?quotations.find(q=>q.id===quotationId):null;
 const existingId=isUuid(existing?.id)?existing.id:null;
 let client=quote&&isUuid(quote.client_id)?clients.find(c=>c._id===quote.client_id):null;
 if(!client&&quote&&isUuid(quote.client_id)){
  const lookup=await window.kasituSupabase.from('clients').select('*').eq('id',quote.client_id).maybeSingle();
  if(lookup.error){alert('Could not load the quotation client: '+lookup.error.message);return}
  const c=lookup.data;
  if(c)client={id:c.client_code,business:c.business_name,contact:c.contact_name||'',email:c.email||'',phone:c.phone||'',service:c.service||'',status:c.status,notes:c.notes||'',_id:c.id};
 }
 if(!client&&existingId&&isUuid(existing.client_id))client=clients.find(c=>c._id===existing.client_id);
 if(!client){alert('Could not find a client record linked to this quotation. Please verify the client selection and try again.');return}
 if(!isUuid(client._id)){alert('The client record has an invalid UUID. Please edit/save the client first, then create the invoice again.');return}
 if(!calc.items.length){alert('Add at least one invoice item.');return}
 let invoiceNumber=existingId?existing.invoice_number:null;
 if(!invoiceNumber)try{invoiceNumber=await nextInvoiceNumber(session)}catch(e){alert(e.message);return}
 let status=v.status;
 if(calc.total>0&&calc.paid>=calc.total)status='Paid';
 else if(calc.paid>0)status='Partially Paid';
 else if(status==='Partially Paid'||status==='Paid')status='Draft';
 const ownerId=await getDataOwnerId(session); const payload={owner_id:ownerId,invoice_number:invoiceNumber,quotation_id:quote?.id||null,client_id:client._id,client_code:client.id,client_name:client.business,client_contact:client.contact||null,client_email:client.email||null,client_phone:client.phone||null,invoice_date:v.invoice_date||today(),due_date:v.due_date||null,status,line_items:calc.items,subtotal:calc.subtotal,discount:calc.discount,vat_rate:calc.vatRate,vat_amount:calc.vat,total:calc.total,amount_paid:calc.paid,balance_due:calc.balance,notes:v.notes||null,terms:v.terms||null};
 const result=existingId?await window.kasituSupabase.from('invoices').update(payload).eq('id',existingId):await window.kasituSupabase.from('invoices').insert(payload);
 if(result.error){alert(result.error.message);return}
 await loadData();closeModal();renderInvoices()
}
function quoteStatus(s){return `<span class="quote-status ${String(s||'Draft').toLowerCase()}">${esc(s||'Draft')}</span>`}
function quoteMini(){if(!quotations.length)return '<div class="empty">No quotations yet.<br><br><button class="btn primary" data-add="quotation">Create first quotation</button></div>';return quotations.slice(0,5).map(q=>`<div class="quote-card"><div class="quote-card-head"><div><div class="quote-number">${esc(q.quote_number)}</div><strong>${esc(q.client_name)}</strong></div><div style="text-align:right"><div class="quote-total">${money(q.total)}</div>${quoteStatus(q.status)}</div></div></div>`).join('')}
function renderQuotations(filter=''){title.textContent='Quotations';const rows=quotations.filter(q=>`${q.quote_number} ${q.client_name} ${q.status}`.toLowerCase().includes(filter.toLowerCase()));content.innerHTML=`<div class="section-head"><div><h2>Quotations</h2><p>Create, track and edit professional quotations.</p></div><div class="quote-toolbar"><input id="quoteSearch" class="search" placeholder="Search quotations..." value="${esc(filter)}"><button class="btn primary" data-add="quotation">+ New Quotation</button></div></div><div class="panel">${quoteTable(rows)}</div>`;document.getElementById('quoteSearch').addEventListener('input',e=>renderQuotations(e.target.value))}
