function quoteForm(q={}){
 q=q||{};const valid=q.valid_until||addDays(q.quote_date||today(),Number(businessSettings.default_quote_validity_days||14));
 return `<div class="form-grid"><div class="field"><label>Client *</label><select name="client_id" required>${clientOptions(q.client_id||'')}</select></div><div class="field"><label>Quotation number</label><input name="quote_number" value="${esc(q.quote_number||'')}" placeholder="Auto-generated on save" readonly></div><div class="field"><label>Quotation date *</label><input type="date" name="quote_date" value="${esc(q.quote_date||today())}" required></div><div class="field"><label>Valid until</label><input type="date" name="valid_until" value="${esc(valid)}"></div><div class="field"><label>Status</label><select name="status">${['Draft','Sent','Approved','Rejected','Expired'].map(x=>`<option ${x===(q.status||'Draft')?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Deposit %</label><input name="deposit_rate" type="number" min="0" max="100" step="0.01" value="${Number(q.deposit_rate??businessSettings.default_deposit_rate??50)}"></div><div class="field"><label>Discount (R)</label><input name="discount" type="number" min="0" step="0.01" value="${Number(q.discount||0).toFixed(2)}"></div><div class="field"><label>VAT rate (%)</label><input name="vat_rate" type="number" min="0" max="100" step="0.01" value="${Number(q.vat_rate??businessSettings.default_vat_rate??0)}"></div></div><div style="margin-top:20px"><div class="panel-head"><h3>Line items</h3><button type="button" class="btn" id="addQuoteLine">+ Add item</button></div><div class="line-items" id="quoteLines">${itemRows(defaultItems(q))}</div></div><div class="quote-summary" id="quoteSummary"></div><div class="field" style="margin-top:20px"><label>Notes</label><textarea name="notes" placeholder="Optional notes for the client">${esc(q.notes||'')}</textarea></div><div class="field" style="margin-top:14px"><label>Terms & conditions</label><textarea name="terms" placeholder="Payment terms, delivery terms, validity, etc.">${esc(q.terms||'Payment is due according to the agreed deposit and balance schedule. Quotation is valid until the date shown above.')}</textarea></div><div class="form-actions"><button type="button" class="btn" id="cancelModal">Cancel</button><button class="btn primary">Save Quotation</button></div>`
}
function collectQuoteItems(){return [...form.querySelectorAll('[data-line-row]')].map(row=>({description:row.querySelector('[name="item_description"]').value.trim(),quantity:Number(row.querySelector('[name="item_qty"]').value||0),unit_price:Number(row.querySelector('[name="item_price"]').value||0)})).filter(i=>i.description||i.unit_price>0)}
function calculateQuote(){const items=collectQuoteItems(),subtotal=items.reduce((s,i)=>s+i.quantity*i.unit_price,0),discount=Math.max(0,Number(form.querySelector('[name="discount"]')?.value||0)),taxable=Math.max(0,subtotal-discount),vatRate=Math.max(0,Number(form.querySelector('[name="vat_rate"]')?.value||0)),vat=taxable*vatRate/100,total=taxable+vat,depositRate=Math.min(100,Math.max(0,Number(form.querySelector('[name="deposit_rate"]')?.value||0))),deposit=total*depositRate/100,balance=Math.max(0,total-deposit);form.querySelector('#quoteSummary').innerHTML=`<div class="quote-summary-row"><span>Subtotal</span><strong>${money(subtotal)}</strong></div><div class="quote-summary-row"><span>Discount</span><strong>− ${money(discount)}</strong></div><div class="quote-summary-row"><span>VAT (${vatRate.toFixed(2)}%)</span><strong>${money(vat)}</strong></div><div class="quote-summary-row total"><span>Total</span><strong>${money(total)}</strong></div><div class="quote-summary-row"><span>Deposit (${depositRate.toFixed(2)}%)</span><strong>${money(deposit)}</strong></div><div class="quote-summary-row"><span>Balance due</span><strong>${money(balance)}</strong></div>`;form.querySelectorAll('[data-line-row]').forEach(row=>{const qty=Number(row.querySelector('[name="item_qty"]').value||0),price=Number(row.querySelector('[name="item_price"]').value||0);row.querySelector('[name="item_total"]').value=money(qty*price)});return {items,subtotal,discount,vatRate,vat,total,depositRate,deposit,balance}}

