function renderMaintenance(filter=''){
 title.textContent='Maintenance';
 if(!maintenanceReady){content.innerHTML='<div class="panel"><h2>Maintenance setup needed</h2><p>Run the SQL in <strong>maintenance-schema.sql</strong> in your Supabase SQL Editor, then refresh this page. Your other Business Manager sections will continue to work.</p></div>';return}
 const rows=maintenance.filter(m=>(m.maintenance_number+' '+m.title+' '+m.client_name+' '+m.service_type+' '+m.status+' '+m.priority).toLowerCase().includes(filter.toLowerCase()));
 const active=maintenance.filter(m=>m.status==='Active').length,paused=maintenance.filter(m=>m.status==='Paused').length,due=maintenance.filter(m=>m.next_service_date&&m.next_service_date<=today()&&!['Completed','Cancelled'].includes(m.status)).length;
 content.innerHTML='<div class="stats"><div class="stat"><div class="stat-label">All plans</div><div class="stat-value">'+maintenance.length+'</div><div class="stat-note">Maintenance records</div></div><div class="stat"><div class="stat-label">Active</div><div class="stat-value">'+active+'</div><div class="stat-note">Currently maintained</div></div><div class="stat"><div class="stat-label">Paused</div><div class="stat-value">'+paused+'</div><div class="stat-note">Temporarily on hold</div></div><div class="stat"><div class="stat-label">Service due</div><div class="stat-value">'+due+'</div><div class="stat-note">Due today or overdue</div></div></div><div class="section-head"><div><h2>Maintenance</h2><p>Track client support plans, service schedules, fees and upcoming maintenance.</p></div><div class="quote-toolbar"><input id="maintenanceSearch" class="search" placeholder="Search maintenance..." value="'+esc(filter)+'"><button class="btn primary" data-add="maintenance">+ New Plan</button></div></div><div class="panel">'+maintenanceTable(rows)+'</div>';
 document.getElementById('maintenanceSearch').addEventListener('input',e=>renderMaintenance(e.target.value))
}
