async function logAudit(action,module,recordId=null,recordLabel='',details={}){try{if(!currentOwnerId)return;await window.kasituSupabase.rpc('log_business_activity',{p_action:action,p_module:module,p_record_id:recordId,p_record_label:recordLabel,p_details:details})}catch(e){console.warn('Audit log failed',e)}}
let auditRows=[];
async function loadAudit(){const {data,error}=await window.kasituSupabase.rpc('get_business_activity',{p_limit:200});if(error){console.error(error);return false}auditRows=data||[];return true}
function auditActionBadge(action){return '<span class="audit-action '+esc(action)+'">'+esc(String(action||'').replace(/_/g,' ').toUpperCase())+'</span>'}
function renderAudit(){title.textContent='Activity Log';if(currentRole!=='owner'){content.innerHTML='<div class="panel"><h2>Access restricted</h2><p>Only the business owner can view the activity log.</p></div>';return}loadAudit().then(ok=>{if(!ok){content.innerHTML='<div class="panel"><h2>Audit log setup required</h2><p>Run <strong>audit-schema.sql</strong> in Supabase, then refresh.</p></div>';return}content.innerHTML='<div class="section-head"><div><h2>Activity Log</h2><p>See who changed what in your Business Manager.</p></div><button class="btn" id="refreshAudit">Refresh</button></div><div class="panel"><div class="table-wrap"><table class="table audit-table"><thead><tr><th>When</th><th>User</th><th>Action</th><th>Area</th><th>Record</th><th>Details</th></tr></thead><tbody>'+ (auditRows.length?auditRows.map(r=>'<tr><td>'+esc(new Date(r.created_at).toLocaleString('en-ZA'))+'</td><td><strong>'+esc(r.actor_email||'Unknown')+'</strong><br><span style="color:var(--muted)">'+esc(String(r.actor_role||'').toUpperCase())+'</span></td><td>'+auditActionBadge(r.action)+'</td><td>'+esc(r.module)+'</td><td>'+esc(r.record_label||r.record_id||'—')+'</td><td><span class="audit-details">'+esc(JSON.stringify(r.details||{}))+'</span></td></tr>').join(''):'<tr><td colspan="6"><div class="empty">No activity recorded yet.</div></td></tr>')+'</tbody></table></div></div>';document.getElementById('refreshAudit')?.addEventListener('click',renderAudit)})}
let teamMembers=[],teamInvitations=[];
async function loadTeamData(){
 const session=await getSession();if(!session)return false;
 const [mr,ir]=await Promise.all([
  window.kasituSupabase.from('business_members').select('user_id,business_owner_id,email,role,status,created_at').order('created_at',{ascending:true}),
  window.kasituSupabase.from('business_invitations').select('id,email,role,expires_at,accepted_at,revoked_at,created_at').order('created_at',{ascending:false})
 ]);
 if(mr.error||ir.error){console.error(mr.error||ir.error);return false}
 teamMembers=mr.data||[];teamInvitations=ir.data||[];return true
}
function teamRoleBadge(role){return '<span class="team-role '+esc(role)+'">'+esc(String(role||'').toUpperCase())+'</span>'}
function teamStatusBadge(status){return '<span class="account-status '+esc(status)+'">'+esc(status)+'</span>'}
function teamMemberActions(member){
 const isOwner=member.role==='owner';
 if(isOwner)return '<span style="color:var(--muted);font-size:11px">Owner</span>';
 return '<div class="team-actions"><button class="btn" data-team-manage="'+esc(member.user_id)+'">Manage</button><button class="btn danger-btn" data-team-remove="'+esc(member.user_id)+'">Remove</button></div>'
}
function openTeamMemberModal(member){
 if(currentRole!=='owner'){alert('Only the business owner can manage team members.');return}
 modal.hidden=false;document.body.style.overflow='hidden';
 modalTitle.textContent='Manage Team Member';
 form.innerHTML='<div class="team-member-modal"><div class="team-member-identity"><strong>'+esc(member.email||'Team member')+'</strong><span>Joined '+esc((member.created_at||'').slice(0,10)||'—')+'</span></div><div class="form-grid"><div class="field"><label>Role</label><select name="role"><option value="manager" '+(member.role==='manager'?'selected':'')+'>Manager</option><option value="staff" '+(member.role==='staff'?'selected':'')+'>Staff</option><option value="viewer" '+(member.role==='viewer'?'selected':'')+'>Viewer</option></select></div><div class="field"><label>Status</label><select name="status"><option value="active" '+(member.status==='active'?'selected':'')+'>Active</option><option value="inactive" '+(member.status==='inactive'?'selected':'')+'>Inactive</option><option value="suspended" '+(member.status==='suspended'?'selected':'')+'>Suspended</option></select></div></div><div class="team-member-warning"><strong>What this changes</strong><span>Role controls what this member can see and edit. Suspended or inactive members lose Business Manager access.</span></div></div><div class="form-actions"><button type="button" class="btn" id="cancelModal">Cancel</button><button class="btn primary">Save Changes</button></div>';
 requestAnimationFrame(()=>form.querySelector('select')?.focus());
 form.onsubmit=async e=>{
  e.preventDefault();
  const v=Object.fromEntries(new FormData(form).entries()),btn=form.querySelector('.btn.primary');
  btn.disabled=true;btn.textContent='Saving…';
  const {error}=await window.kasituSupabase.rpc('update_business_member',{p_user_id:member.user_id,p_role:v.role,p_status:v.status});
  btn.disabled=false;btn.textContent='Save Changes';
  if(error){alert(error.message);return}
  await logAudit('updated','team',member.user_id,member.email,{role:v.role,status:v.status});closeModal();await loadData();renderTeam()
 };
 document.getElementById('cancelModal')?.addEventListener('click',closeModal,{once:true})
}
async function removeTeamMember(userId){
 if(currentRole!=='owner'){alert('Only the business owner can remove team members.');return}
 const member=teamMembers.find(m=>m.user_id===userId);
 if(!member||member.role==='owner'){alert('The business owner cannot be removed from the team.');return}
 if(!confirm('Remove '+(member.email||'this team member')+' from Business Manager? Their personal Supabase account will remain intact.'))return;
 const {error}=await window.kasituSupabase.rpc('remove_business_member',{p_user_id:userId});
 if(error){alert(error.message);return}
 await loadData();renderTeam()
}
function renderTeam(){
 title.textContent='Team';
 return loadTeamData().then(ok=>{
  if(!ok){content.innerHTML='<div class="panel"><h2>Team setup required</h2><p>Run <strong>team-schema.sql</strong> in Supabase SQL Editor, then refresh.</p></div>';return}
  const members=teamMembers.filter(m=>m.user_id!==undefined);
  const pending=teamInvitations.filter(i=>!i.accepted_at&&!i.revoked_at&&new Date(i.expires_at)>new Date());
  content.innerHTML='<div class="section-head"><div><h2>Team Management</h2><p>Manage who can access your KASITU Business Manager.</p></div><span class="mode-badge">TEAM MANAGEMENT</span></div>'+
   '<div class="team-grid">'+
   '<section class="panel"><div class="settings-section-head"><span class="settings-icon">👥</span><div><h3>Invite a team member</h3><p>Create a secure invite link that expires after 7 days.</p></div></div>'+
   '<form id="teamInviteForm" class="form-grid team-invite-form"><div class="field"><label>Email address *</label><input name="email" type="email" maxlength="254" required placeholder="staff@example.com"></div>'+
   '<div class="field"><label>Role *</label><select name="role"><option value="manager">Manager</option><option value="staff" selected>Staff</option><option value="viewer">Viewer</option></select></div>'+
   '<div class="field full"><div class="settings-save-row"><button class="btn primary" type="submit">Create invite link</button><span id="teamInviteMessage" role="status" aria-live="polite"></span></div></div></form>'+
   '<div id="teamInviteResult" class="team-invite-result" hidden></div></section>'+
   '<section class="panel"><div class="settings-section-head"><span class="settings-icon">♙</span><div><h3>Current team</h3><p>Active and inactive users connected to this business.</p></div></div>'+
   '<div class="table-wrap"><table class="table team-table"><thead><tr><th>Email</th><th>Role</th><th>Status</th><th>Joined</th><th>Actions</th></tr></thead><tbody>'+
   (members.length?members.map(m=>'<tr><td><strong>'+esc(m.email||'Account email')+'</strong></td><td>'+teamRoleBadge(m.role)+'</td><td>'+teamStatusBadge(m.status)+'</td><td>'+esc((m.created_at||'').slice(0,10)||'—')+'</td><td>'+teamMemberActions(m)+'</td></tr>').join(''):'<tr><td colspan="5"><div class="empty">No team members found.</div></td></tr>')+
   '</tbody></table></div></section></div>'+
   '<section class="panel team-pending"><div class="settings-section-head"><span class="settings-icon">✉</span><div><h3>Pending invitations</h3><p>Unused invitation links can be revoked at any time.</p></div></div>'+
   (pending.length?'<div class="table-wrap"><table class="table team-table"><thead><tr><th>Email</th><th>Role</th><th>Expires</th><th></th></tr></thead><tbody>'+pending.map(i=>'<tr><td>'+esc(i.email)+'</td><td>'+teamRoleBadge(i.role)+'</td><td>'+esc(new Date(i.expires_at).toLocaleString('en-ZA'))+'</td><td><button class="btn danger-btn" data-revoke-invite="'+esc(i.id)+'">Revoke</button></td></tr>').join('')+'</tbody></table></div>':'<div class="empty">No pending invitations.</div>')+
   '</section>';
  const f=document.getElementById('teamInviteForm');
  f.addEventListener('submit',async e=>{
   e.preventDefault();const btn=f.querySelector('button[type="submit"]'),msg=document.getElementById('teamInviteMessage'),result=document.getElementById('teamInviteResult'),v=Object.fromEntries(new FormData(f).entries());
   btn.disabled=true;msg.textContent='Creating secure invite…';result.hidden=true;
   const {data,error}=await window.kasituSupabase.rpc('create_business_invitation',{p_email:v.email,p_role:v.role});
   btn.disabled=false;
   if(error){msg.textContent='Could not create invite: '+error.message;return}
   const row=Array.isArray(data)?data[0]:data;const token=row?.invite_token;
   if(!token){msg.textContent='Invite was created, but no token was returned.';return}
   const inviteUrl=new URL('accept-invite.html',window.location.href);inviteUrl.searchParams.set('token',token);
   result.innerHTML='<strong>Invite link ready</strong><span>Send this link to '+esc(v.email)+'. It expires in 7 days.</span><div class="team-invite-link"><input readonly value="'+esc(inviteUrl.toString())+'"><button type="button" class="btn primary" id="copyTeamInvite">Copy link</button></div>';
   result.hidden=false;msg.textContent='Invite created successfully.';f.reset();f.querySelector('[name="role"]').value='staff';
   document.getElementById('copyTeamInvite').addEventListener('click',async()=>{await navigator.clipboard.writeText(inviteUrl.toString());document.getElementById('copyTeamInvite').textContent='Copied';setTimeout(()=>document.getElementById('copyTeamInvite').textContent='Copy link',1600)});
   await loadTeamData();
   const pendingNow=teamInvitations.filter(i=>!i.accepted_at&&!i.revoked_at&&new Date(i.expires_at)>new Date());
   const pendingPanel=document.querySelector('.team-pending');
   if(pendingPanel){
    pendingPanel.innerHTML='<div class="settings-section-head"><span class="settings-icon">✉</span><div><h3>Pending invitations</h3><p>Unused invitation links can be revoked at any time.</p></div></div>'+
     (pendingNow.length?'<div class="table-wrap"><table class="table team-table"><thead><tr><th>Email</th><th>Role</th><th>Expires</th><th></th></tr></thead><tbody>'+pendingNow.map(i=>'<tr><td>'+esc(i.email)+'</td><td>'+teamRoleBadge(i.role)+'</td><td>'+esc(new Date(i.expires_at).toLocaleString('en-ZA'))+'</td><td><button class="btn danger-btn" data-revoke-invite="'+esc(i.id)+'">Revoke</button></td></tr>').join('')+'</tbody></table></div>':'<div class="empty">No pending invitations.</div>');
   }
  });
 });
}
function bindNavigation(){document.querySelectorAll('.nav-item[data-view]').forEach(btn=>btn.addEventListener('click',()=>{sidebar.classList.remove('open');render(btn.dataset.view);document.querySelectorAll('.nav-item').forEach(x=>x.classList.remove('active'));btn.classList.add('active')}));document.getElementById('mobileMenu').addEventListener('click',()=>sidebar.classList.toggle('open'));document.getElementById('modalClose').addEventListener('click',closeModal);modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});document.getElementById('signOutButton').addEventListener('click',async()=>{await window.kasituSupabase.auth.signOut();window.location.replace('login.html')})}
function bindNavigationButtons(){document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>document.querySelector(`[data-view="${b.dataset.go}"]`)?.click()));document.querySelectorAll('[data-add="project"]').forEach(b=>b.addEventListener('click',()=>openModal('Project')));document.querySelectorAll('[data-add="client"]').forEach(b=>b.addEventListener('click',()=>openModal('Client')));document.querySelectorAll('[data-add="lead"]').forEach(b=>b.addEventListener('click',()=>openModal('Lead')));document.querySelectorAll('[data-add="quotation"]').forEach(b=>b.addEventListener('click',()=>openModal('Quotation')));document.querySelectorAll('[data-add="invoice"]').forEach(b=>b.addEventListener('click',()=>openModal('Invoice')));document.querySelectorAll('[data-add="payment"]').forEach(b=>b.addEventListener('click',()=>openModal('Payment')));document.querySelectorAll('[data-add="maintenance"]').forEach(b=>b.addEventListener('click',()=>openModal('Maintenance')));document.querySelectorAll('[data-add="expense"]').forEach(b=>b.addEventListener('click',()=>openModal('Expense')));document.querySelectorAll('[data-add="document"]').forEach(b=>b.addEventListener('click',()=>openModal('Document')))}
function render(view){if(!canView(view)){title.textContent='Access restricted';content.innerHTML='<div class="panel"><h2>Access restricted</h2><p>Your current role is <strong>'+esc(String(currentRole).toUpperCase())+'</strong> and does not have access to this area.</p></div>';applyRoleUI();return}if(view==='projects')renderProjects();else if(view==='maintenance')renderMaintenance();else if(view==='expenses')renderExpenses();else if(view==='documents')renderDocuments();else if(view==='reports')renderReports();else if(view==='settings')renderSettings();else if(view==='account')renderAccount();else if(view==='team')renderTeam();else if(view==='audit')renderAudit();else if(view==='clients')renderClients();else if(view==='leads')renderLeads();else if(view==='quotations')renderQuotations();else if(view==='invoices')renderInvoices();else if(view==='payments')renderPayments();else renderDashboard();bindNavigationButtons();applyRoleUI()}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]')?.dataset.add;if(add&&!requireWrite(add))return;const cid=e.target.closest('[data-edit-client]')?.dataset.editClient;if(cid){if(!requireWrite('clients'))return;openModal('Client',clients.find(c=>c.id===cid));return}const lid=e.target.closest('[data-edit-lead]')?.dataset.editLead;if(lid){if(!requireWrite('leads'))return;openModal('Lead',leads.find(l=>l.id===lid));return}const qid=e.target.closest('[data-edit-quote]')?.dataset.editQuote;if(qid){if(!requireWrite('quotations'))return;openModal('Quotation',quotations.find(q=>q.id===qid));return}const ciid=e.target.closest('[data-create-invoice]')?.dataset.createInvoice;if(ciid){if(!requireWrite('invoices'))return;const q=quotations.find(x=>x.id===ciid);const client=q?clients.find(c=>c._id===q.client_id):null;openModal('Invoice',{quotation_id:q?.id||'',client_id:client?._id||'',client_name:client?.business||q?.client_name||'',items:q?.items||[],subtotal:q?.subtotal||0,discount:q?.discount||0,vat_rate:q?.vat_rate||0,total:q?.total||0,amount_paid:0,balance_due:q?.total||0,status:'Draft',invoice_date:today(),due_date:addDays(today(),7),notes:'Invoice created from '+(q?.quote_number||'quotation')});return}const iid=e.target.closest('[data-edit-invoice]')?.dataset.editInvoice;if(iid){if(!requireWrite('invoices'))return;openModal('Invoice',invoices.find(i=>i.id===iid));return}const projid=e.target.closest('[data-edit-project]')?.dataset.editProject;if(projid){if(!requireWrite('projects'))return;openModal('Project',projects.find(p=>p.id===projid));return}const maintid=e.target.closest('[data-edit-maintenance]')?.dataset.editMaintenance;if(maintid){if(!requireWrite('maintenance'))return;openModal('Maintenance',maintenance.find(m=>m.id===maintid));return}const exid=e.target.closest('[data-edit-expense]')?.dataset.editExpense;if(exid){if(!requireWrite('expenses'))return;openModal('Expense',expenses.find(x=>x.id===exid));return}const delid=e.target.closest('[data-delete-expense]')?.dataset.deleteExpense;if(delid){if(!requireWrite('expenses'))return;deleteExpense(delid);return}const docid=e.target.closest('[data-edit-document]')?.dataset.editDocument;if(docid){if(!requireWrite('documents'))return;openModal('Document',documents.find(d=>d.id===docid));return}const ddel=e.target.closest('[data-delete-document]')?.dataset.deleteDocument;if(ddel){if(!requireWrite('documents'))return;deleteDocument(ddel);return}const dview=e.target.closest('[data-download-document]')?.dataset.downloadDocument;if(dview){downloadDocument(dview);return}const pid=e.target.closest('[data-edit-payment]')?.dataset.editPayment;if(pid){if(!requireWrite('payments'))return;openModal('Payment',payments.find(p=>p.id===pid));return}const rid=e.target.closest('[data-revoke-invite]')?.dataset.revokeInvite;if(rid){if(currentRole!=='owner'){alert('Only the business owner can revoke invitations.');return}(async()=>{if(!confirm('Revoke this invitation?'))return;const {error}=await window.kasituSupabase.rpc('revoke_business_invitation',{p_invitation_id:rid});if(error){alert(error.message);return}await logAudit('revoked','team_invitation',rid,'Invitation');renderTeam()})();return}const muid=e.target.closest('[data-team-manage]')?.dataset.teamManage;if(muid){if(currentRole!=='owner')return;const member=teamMembers.find(m=>m.user_id===muid);if(member)openTeamMemberModal(member);return}const rmuid=e.target.closest('[data-team-remove]')?.dataset.teamRemove;if(rmuid){removeTeamMember(rmuid);return}if(e.target.id==='cancelModal')closeModal()});
(async()=>{if(!window.supabase||!window.KASITU_SUPABASE_URL||!window.KASITU_SUPABASE_PUBLISHABLE_KEY){content.innerHTML='<div class="panel"><h2>Configuration missing</h2><p>Supabase configuration is missing.</p></div>';return}window.kasituSupabase=window.supabase.createClient(window.KASITU_SUPABASE_URL,window.KASITU_SUPABASE_PUBLISHABLE_KEY);const session=await getSession();if(!session)return;const access=await window.kasituSupabase.from('business_members').select('business_owner_id,role,status').eq('user_id',session.user.id).maybeSingle();if(access.error){content.innerHTML='<div class="panel"><h2>Access check failed</h2><p>'+esc(access.error.message)+'</p></div>';bindNavigation();return}if(!access.data||access.data.status!=='active'){currentRole=access.data?.role||'staff';currentStatus=access.data?.status||'inactive';currentOwnerId=access.data?.business_owner_id||null;title.textContent='Access restricted';content.innerHTML='<div class="panel"><h2>Access restricted</h2><p>Your Business Manager access is currently <strong>'+esc(String(currentStatus).toUpperCase())+'</strong>.</p><p>You can still sign out safely.</p><button type="button" class="btn danger-btn" id="suspendedSignOut">Sign out</button></div>';bindNavigation();document.getElementById('suspendedSignOut')?.addEventListener('click',async()=>{await window.kasituSupabase.auth.signOut();window.location.replace('login.html')});return}currentRole=access.data.role||'owner';currentStatus=access.data.status;currentOwnerId=access.data.business_owner_id||session.user.id;const ok=await loadData();if(!ok)return;await loadBusinessSettings();bindNavigation();renderDashboard();applyRoleUI()})();